class Solution {
  public int[] findSubtreeSizes(int[] parent, String s) {
    int n = parent.length;
    int[] start = new int[n + 1];
    for (int i = 1; i < n; i++) start[parent[i] + 1]++;
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], kids = new int[n];
    for (int i = 1; i < n; i++) kids[start[parent[i]] + fill[parent[i]]++] = i;
    int[] order = new int[n];
    int head = 0, tail = 0;
    order[tail++] = 0;
    int[][] near = new int[n][];
    near[0] = new int[26];
    java.util.Arrays.fill(near[0], -1);
    near[0][s.charAt(0) - 'a'] = 0;
    int[] np = new int[n];
    np[0] = -1;
    while (head < tail) {
      int u = order[head++];
      for (int p = start[u]; p < start[u + 1]; p++) {
        int v = kids[p], c = s.charAt(v) - 'a';
        np[v] = near[u][c] >= 0 ? near[u][c] : u;
        near[v] = near[u].clone();
        near[v][c] = v;
        order[tail++] = v;
      }
      near[u] = null;
    }
    int[] size = new int[n];
    java.util.Arrays.fill(size, 1);
    for (int i = n - 1; i > 0; i--) size[np[order[i]]] += size[order[i]];
    return size;
  }
}
